.container {
    display: flex;
    flex-direction: column;
    width: 100%;
    min-height: 100%;
    background-color: #f0f0f0;
}

.header {
    position: fixed;
    width: 100%;
    height: 50px;
    background: #d9f5ff;
    z-index: 10;

    &__content {
        position: relative;
        display: flex;
        flex-direction: row;
        width: 1100px;
        height: 100%;
        margin: 0 auto;
    }
}

.content {
    display: flex;
    flex-grow: 1;
    width: 1100px;
    margin: 0 auto;
    padding: 50px 0 0 0;
}

.list {
    flex-grow: 1;
    margin: 20px 0;
    overflow: hidden;
}

.feeds {
    margin: 20px 0 0 20px;
}

/*
* grid
*/

.grid .header {
    &__content {
        width: 90%;
    }
}

.grid .content {
    width: 90%;
    padding-top: 120px;
}

.grid .feeds {
    position: fixed;
    width: 100%;
    top: 50px;
    margin: 0;
    z-index: 1;
}

/*
* theme
*/

.container.dark {
    background-color: #212121;
}

.dark .header {
    background: #1b1c1d;
}

.dark .feeds {
    background-color: #212121;
}

/*
* media
*/

@media (max-width: 768px) {
    .header {
        box-sizing: border-box;
        padding: 0 0 0 20px;

        &__content {
            width: 100%;
            max-width: 100%;
        }
    }

    .content {
        width: 100%;
        flex-direction: column-reverse;
        padding: 120px 0 0 0;
    }

    .feeds {
        position: fixed;
        top: 50px;
        left: 0;
        margin: 0;
        width: 100%;
        max-width: 100%;
    }
}

.entries-list {
	display: flex;
	flex-direction: column;
	width: 100%;
}

.grid .entries-list {
	display: grid;
  grid-template-columns: 1fr 1fr 1fr;
	grid-column-gap: 20px;
}

@media (min-width: 1100px) {
	.grid .entries-list {
		grid-template-columns: 1fr 1fr 1fr 1fr;
	}
}

.entry-item {
	position: relative;
	flex-shrink: 0;
	width: 100%;
  margin: 0 0 20px 0;
  padding: 20px;
  box-sizing: border-box;
	background: #ffffff;

	&__title {
		margin: 0 0 15px 0;
		font-size: 18px;
		font-weight: bold;
		line-height: 22px;
	}

	&__title a {
		color: #000000;
		text-decoration: none;
	}

	&__description {
		position: relative;
		margin: 20px 0 0 0;
		font-size: 14px;
		line-height: 18px;
		color: #000000;
		overflow: hidden;
	}

	&_collapsed &__description {
		max-height: 800px;
	}

	&__description img {
		max-width: 100%;
		height: auto;
		margin: 0 auto 10px auto;
		padding: 0px;
	}

	&__description font {
		color: #000000 !important;
	}

	&__description p {
		margin: 0 0 10px 0;
	}

	&__description code {
		font-family: inherit;
	}

	&__description blockquote {
		font-style: italic;
		color: #767676;
		margin: 0;
	}

	&__description h1,
	&__description h2 {
		font-size: 14px;
			margin: 0;
	}

	&__description ol {
		margin: 0;
		padding: 0 0 0 20px;
	}

	&__description a {
		color: #4076cc;
	}

	&__description pre {
		white-space: pre-wrap;
	}
}

.entry-item-expand-button {
	position: absolute;
	left: 0;
	right: 0;
	bottom: 58px;
	height: 60px;
	width: 100%;
	background: rgba(255, 255, 255, 0.8);
	cursor: pointer;
}

.entry-item-feed {
	display: flex;
	margin: 10px 0;

	&__title {
		margin: auto 0 auto 10px;
		font-size: 12px;
		color: #909090;
	}

	&__icon {
		width: 14px;
		height: 14px;
		margin: auto 0;
		background-image: "";
		background-repeat: no-repeat;
		background-size: cover;
		background-color: #ebebeb;
	}
}

.entry-item-info {
	display: flex;
	width: 100%;
	margin: 20px 0 0 0;

	&__item {
		display: flex;
		margin: auto 15px auto 0;
		cursor: pointer;
	}

	&__icon {
		width: 18px;
		height: 18px;
		margin: auto 0;
		fill: #818181;
	}
}

/*
* theme
*/

.dark .entry {
	background-color: #1d1d1d;

	&__title a {
		color: #bfbfbf;
	}

	&__description {
		color: #bfbfbf;
	}

	&__description font {
		color: #bfbfbf !important;
	}

	&__expandButton {
		background-color: rgba(29, 29, 29, 0.8);
	}
}

.feed-edit {
	display: flex;
	height: 30px;
	margin: 30px 0 0 0;
	padding: 0;
	opacity: 1;
	transition: opacity 0.2s ease-in-out;

	&_disabled {
		opacity: 0.6;
		pointer-events: none;
	}

	&_scrolled {
		opacity: 0;
		pointer-events: none;
	}

	&__button {
		display: flex;
		padding: 0;
		margin: auto 10px auto 0;
		cursor: pointer;
	}

	&__icon {
		width: 16px;
		height: 16px;
		stroke: #000000;
		stroke-width: 2px;
		fill: #000000;

		&_editing {
			stroke: #2f74f1;
		}

		svg {
			width: 100%;
			height: 100%;
		}
	}
}

.feed-edit-form {
	display: flex;
	width: 100%;


	&__button {
		display: flex;
		padding: 0;
		margin: auto 0 auto 10px;
		cursor: pointer;
	}

	&__field {
		flex-grow: 1;
		margin: auto 0;
		font-size: 14px;
	}
}

/*
* grid
*/

.grid .feed-edit {
	margin: auto 0 auto auto;
}

/*
* theme
*/

.dark .feed-edit {
	&__icon {
		stroke: #a5a5a5;
		fill: #a5a5a5;
	}
}

@media (max-width: 768px) {
	.feed-edit {
		margin: 0;
	}
}

.feed-item {
  display: flex;
  flex-direction: row;
  width: 100%;
  height: 30px;

  &__button {
    display: flex;
    flex-direction: row;
    overflow: hidden;
    cursor: pointer;
  }

  &__icon {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
    margin: auto 10px auto 0;
    background-image: "";
    background-repeat: no-repeat;
    background-size: cover;
    background-color: #ebebeb;
  }

  &__label {
    margin: auto 0;
    font-size: 13px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    color: #000000;

    &_selected {
      font-weight: bold;
    }
  }

  &__counter {
    margin: auto 0 auto 10px;
    padding: 2px 5px;
    font-size: 11px;
    color: #ffffff;
    border-radius: 2px;
    background-color: #4da0da;
  }

  &__edit_panel {
    display: flex;
    flex-direction: row;
    width: 100%;
  }

  &__edit_button {
    padding: 0;
    margin: auto 0 auto 10px;
    display: flex;
    cursor: pointer;

    .icon {
      width: 16px;
      height: 16px;
      stroke: #000000;
      stroke-width: 2px;
      fill: #000000;

      svg {
        width: 100%;
        height: 100%;
      }
    }
  }

  &__title_field {
    margin: auto 10px auto 0;
    font-size: 13px;
    flex-grow: 1;
  }
}

/*
* grid
*/

.grid .feed-item {
  width: auto;
  height: 30px;
  margin: auto 20px auto 0;
}

/*
* theme
*/

.dark .feed-item {
  &__icon {
    background-color: #bfbfbf;
  }

  &__label {
    color: #bfbfbf;

    &--selected {
      color: #f3f3f3;
    }
  }

  &__edit_button {
    .icon {
      stroke: #a5a5a5;
      fill: #a5a5a5;
    }
  }
}

@media (max-width: 768px) {
  .feed-item {
    flex-shrink: 0;
    width: auto;
    margin-right: 20px;
  }
}

.feeds-list {
  position: sticky;
  display: flex;
  flex-direction: column;
  top: 70px;
  width: 300px;
  padding: 20px;
  background: #ffffff;
}

@media (max-width: 768px) {
  .feeds-list {
    position: relative;
    flex-direction: row;
    top: auto;
    width: auto;
    overflow: auto;
  }
}

/*
* grid
*/

.grid .feeds-list {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  top: 0;
  width: 90%;
  height: 70px;
  padding: 0;
  margin: 0 auto;
  background: transparent;
}

/*
* theme
*/

.dark .feeds-list {
  background-color: #1d1d1d;
}

.grid.dark .feeds-list {
  background: transparent;
}

.menu {
	display: flex;
	height: 100%;
	margin: 0 auto 0 0;
}


@media (max-width: 768px) {
	.menu {
		overflow: auto;
	}
}

.menu-button {
	display: flex;
	flex-direction: row;
	flex-shrink: 0;
	height: 100%;
	margin: 0 20px 0 0;
	cursor: pointer;

	&__label {
		margin: auto 0;
		font-size: 14px;
		color: #000000;

		&_-selected {
			font-weight: bold;
		}
	}

	&__counter {
		margin: auto 0 auto 10px;
		padding: 2px 5px;
		font-size: 11px;
		border-radius: 2px;
		color: #ffffff;
    background-color: #4da0da;
	}
}

/*
* theme
*/

.dark .menu-button {
	&__label {
		color: #bfbfbf;

		&_selected {
			color: #f3f3f3;
		}
	}

	&__counter {
		color: #ffffff;
		background-color: #4da0da;
	}
}

.reload-button {
	display: flex;
	flex-direction: row;
	flex-shrink: 0;
	overflow: hidden;
	margin: 0;
	opacity: 1;
	transition: opacity 0.2s ease-in-out;

	&_active {
		opacity: 0.6;
		pointer-events: none;
	}

	&__icon {
  	width: 16px;
		height: 16px;
		margin: auto 10px auto 0;
		stroke: #000000;
		stroke-width: 2px;
		fill: none;
		cursor: pointer;

		&_active {
			animation: spin 2s linear infinite;
		}

		&_error {
			stroke: #ff0000;
		}
	}

	&__icon > svg {
		width: 100%;
  	height: 100%;
	}
}

/*
* theme
*/

.dark .reload-button {
	&__icon {
		stroke: #f3f3f3;
	}
}

@keyframes spin {
	100% {
		transform: rotate(360deg);
	}
}

.settings {
  position: absolute;
  right: 0;
  top: 100%;
  display: flex;
  flex-direction: column;
  padding: 10px 20px;
  border-radius: 4px 0 4px 4px;
  background: #ffffff;
  box-shadow: 0 10px 10px 1px rgba(0, 0, 0, 0.1);

  &__item {
    width: 100%;
    height: 40px;
    display: flex;
  }

  &__label {
    margin: auto 0;
    font-size: 14px;
  }

  &__checkbox {
    margin: auto 10px auto 0;
  }

  &__days {
    width: 30px;
    margin: 0 5px;
    text-align: right;
  }
}

.settings_button {
  flex-shrink: 0;
  margin: 0;
  padding: 0 12px;
  transition: background-color 200ms ease-in;
  cursor: pointer;

  &_active {
    background-color: #ffffff;
  }

  &__icon {
    width: 20px;
    height: 20px;
    fill: #404040;
    stroke: none;
  }
}

/*
* theme
*/

.dark .settings_button {
  &__icon {
    fill: #d4d4d4;

    &_active {
      fill: #404040;
    }
  }
}

html {
	margin: 0;
	padding: 0;
	height: 100%;
	width: 100%;
	font-family: i8sans,"Helvetica Neue","Arial",sans-serif;
}

body {
	height: 100%;
	width: 100%;
  margin: 0;
	padding: 0;
  background: #f0f0f0;
}

button {
  	border: none;
  	background: none;
  	outline: 0;
 	padding: 0;
  	margin: 0;
}

#root {
	width: 100%;
    height: 100%;
}

@keyframes spin {
	100% {
		transform: rotate(360deg);
	}
}

.fade-enter {
	opacity: 0;
}

.fade-enter-active {
	opacity: 1;
	transition: opacity 200ms ease-in;
}

.fade-exit {
	opacity: 1;
}

.fade-exit-active {
	opacity: 0;
	transition: opacity 200ms ease-out;
}

export function debounce(func: (...args: any[]) => void, wait: number, immediate: boolean): () => void {
	let timeout: number | null;

	return (...args: any[]) => {
		const later = function() {
			timeout = null;
			if (!immediate) func.apply(this, args);
		};

		const callNow = immediate && !timeout;

		timeout && clearTimeout(timeout);

		timeout = window.setTimeout(later, wait);

		if (callNow) func.apply(this, args);
	};
}
